import test from 'node:test';import assert from 'node:assert/strict';
import {catalog,createRound,choose,retry,next,evidence,source} from '../dist/curriculum-model.js';
import {startParentFlowPreview} from '../dev/parent-flow-preview.js';
for(const s of catalog){test(`${s.id}: original round preserves wrong and assisted evidence`,()=>{const r=createRound(s.id);assert.equal(choose(r,'invalid'),false);assert.equal(next(r),false);const q=s.questions[0];choose(r,q.choices.find(x=>x!==q.answer));assert.equal(r.phase,'hint');assert.equal(choose(r,q.answer),false);retry(r);choose(r,q.answer);next(r);choose(r,s.questions[1].answer);next(r);assert.equal(r.phase,'complete');assert.deepEqual(evidence(r).map(x=>[x.correct,x.assisted]),[[false,false],[true,true],[true,false]]);assert.equal(next(r),false);});}
test('catalog has three subjects, valid originals, and official source',()=>{assert.equal(catalog.length,3);assert.match(source.url,/^https:\/\/edu.sh.gov.cn\//);assert.throws(()=>createRound('__proto__'));for(const s of catalog){assert.equal(s.questions.length,2);for(const q of s.questions){assert.equal(new Set(q.choices).size,q.choices.length);assert.ok(q.choices.includes(q.answer));assert.ok(q.hint&&q.reason);}}});
test('local-only curriculum route serves without altering original app',async()=>{const p=await startParentFlowPreview();try{for(const path of ['curriculum.html','curriculum.css','curriculum-model.js','curriculum-ui.js'])assert.equal((await fetch(p.origin+'/'+path)).status,200);assert.match(await(await fetch(p.origin)).text(),/curriculum.html/);assert.match((await fetch(p.origin+'/curriculum.html')).headers.get('content-security-policy'),/connect-src 'none'/);}finally{await p.close();}});
